"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { api } from "@/trpc/react";
import { ArrowRight, Check, Cpu, Server, ShieldCheck } from "lucide-react";
import { useEffect, useState } from "react";

interface WizardWelcomeStepProps {
    onNext: (mode: "standard" | "compatibility") => void;
}

export function WizardWelcomeStep({ onNext }: WizardWelcomeStepProps) {
    const [selectedMode, setSelectedMode] = useState<"standard" | "compatibility" | null>(null);

    // Check hardware detection
    const { data: hardwareInfo, isLoading } = api.system.detectHardware.useQuery(undefined, {
        refetchOnWindowFocus: false,
    });

    // Automatically recommend compatibility mode if RAID is detected
    useEffect(() => {
        if (hardwareInfo?.hasRaid) {
            setSelectedMode("compatibility");
        }
    }, [hardwareInfo]);

    const handleContinue = () => {
        if (selectedMode) {
            onNext(selectedMode);
        }
    };

    return (
        <div className="max-w-5xl mx-auto p-6 space-y-8">
            <div className="text-center space-y-4">
                <h1 className="text-4xl font-extrabold tracking-tight lg:text-5xl">
                    Welcome to Ganache
                </h1>
                <p className="text-xl text-muted-foreground max-w-2xl mx-auto">
                    Choose how you want to configure your storage cluster.
                </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-8">
                {/* Standard Mode Card */}
                <Card
                    className={`relative cursor-pointer transition-all border-2 hover:border-primary/50 ${selectedMode === "standard" ? "border-primary shadow-lg scale-[1.02]" : "border-border"}`}
                    onClick={() => setSelectedMode("standard")}
                >
                    <CardHeader>
                        <div className="w-12 h-12 bg-primary/10 rounded-lg flex items-center justify-center mb-4">
                            <Server className="w-6 h-6 text-primary" />
                        </div>
                        <CardTitle className="text-2xl">Standard Mode</CardTitle>
                        <CardDescription>
                            For standard hardware with direct disk access (HBA/IT Mode).
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-2 text-sm text-muted-foreground">
                        <p>• Best performance (ZFS Native)</p>
                        <p>• Full S.M.A.R.T. monitoring</p>
                        <p>• Recommended for most setups</p>
                    </CardContent>
                    {selectedMode === "standard" && (
                        <div className="absolute top-4 right-4 text-primary">
                            <Check className="w-6 h-6" />
                        </div>
                    )}
                </Card>

                {/* Compatibility Mode Card */}
                <Card
                    className={`relative cursor-pointer transition-all border-2 hover:border-blue-500/50 ${selectedMode === "compatibility" ? "border-blue-500 shadow-lg scale-[1.02]" : "border-border"}`}
                    onClick={() => setSelectedMode("compatibility")}
                >
                    <CardHeader>
                        <div className="flex justify-between items-start">
                            <div className="w-12 h-12 bg-blue-500/10 rounded-lg flex items-center justify-center mb-4">
                                <ShieldCheck className="w-6 h-6 text-blue-500" />
                            </div>
                            {/* Hardware Detected Badge */}
                            {hardwareInfo?.hasRaid && (
                                <Badge variant="secondary" className="bg-blue-100 text-blue-700 hover:bg-blue-100 gap-1">
                                    <Cpu className="w-3 h-3" />
                                    Hardware Detected: {hardwareInfo.controllerName || "RAID Controller"}
                                </Badge>
                            )}
                        </div>
                        <CardTitle className="text-2xl">Compatibility Mode</CardTitle>
                        <CardDescription>
                            Optimized for hardware RAID controllers.
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div className="space-y-2 text-sm text-muted-foreground">
                            <p>• Works with existing RAID cards (PERC, etc.)</p>
                            <p>• Safe ZFS layering on virtual drives</p>
                            <p>• Automatic performance tuning</p>
                        </div>

                        {/* Educator Tooltip / Info Box */}
                        {hardwareInfo?.hasRaid && (
                            <div className="bg-blue-50 text-blue-700 text-xs p-3 rounded-md border border-blue-100 mt-4">
                                <strong>Why is this recommended?</strong><br />
                                We detected a hardware RAID controller. Compatibility mode ensures ZFS runs safely on top of your existing virtual drives without data corruption risks.
                            </div>
                        )}
                    </CardContent>
                    {selectedMode === "compatibility" && (
                        <div className="absolute top-4 right-4 text-blue-500">
                            <Check className="w-6 h-6" />
                        </div>
                    )}
                </Card>
            </div>

            <div className="flex justify-center pt-8">
                <Button
                    size="lg"
                    onClick={handleContinue}
                    disabled={!selectedMode || isLoading}
                    className="w-full md:w-auto min-w-[200px] text-lg h-12"
                >
                    {isLoading ? "Scanning Hardware..." : (
                        <>
                            Continue Setup <ArrowRight className="ml-2 w-5 h-5" />
                        </>
                    )}
                </Button>
            </div>
        </div>
    );
}
